'use strict';
(async()=>{
 const local=['terminal.local','localhost','127.0.0.1'].includes(location.hostname),scripts=['storage-context.js','seed.js','recipe-catalog.js','core.js','spending-core.js','purchase-units.js','planning-core.js','insights-core.js','family-menu-core.js','availability-core.js','personal-core.js','app.js','artwork.js','unit-picker.js','family-features.js','shopping-planning.js','push-ui.js','simple-view.js','language.js','push-settings-ui.js','insights-ui.js','products-ui.js','family-menu-ui.js','household-ui.js','personal-ui.js'];
 try{if(localStorage.getItem('bep-local-locked')==='yes'){location.replace('/login?locked=1');return}}catch{}
 const lock=message=>{document.body.innerHTML='';const main=document.createElement('main'),h=document.createElement('h1'),p=document.createElement('p'),a=document.createElement('a');h.textContent='Bếp Gia Đình';p.textContent=message;a.textContent='Đăng nhập';a.href='/login';main.append(h,p,a);document.body.append(main)};
 if(!local){try{const response=await fetch('/.netlify/functions/family?op=status',{credentials:'same-origin',cache:'no-store'});if([401,403].includes(response.status)){clearOfflineAccess();lock('Cần đăng nhập lại khi có mạng. Dữ liệu trên máy vẫn được giữ.');return}if(!response.ok||!response.headers.get('content-type')?.includes('application/json'))throw Error();const status=await response.json();if(!status.configured||!status.connected){clearOfflineAccess();location.replace('/login?return='+encodeURIComponent(location.pathname)+location.hash);return}window.BEP_SESSION=status;await rememberOfflineAccess(status);sessionStorage.setItem('bep-access-checked','yes')}catch{const offline=await readOfflineAccess();if(!offline){lock('Cần mạng cho lần đăng nhập đầu tiên hoặc khi quyền offline đã hết hạn. Dữ liệu trên máy vẫn được giữ.');return}window.BEP_SESSION=offline;window.BEP_OFFLINE=true}}
 for(const src of scripts){try{await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=reject;document.body.append(script)})}catch{lock('Chưa tải được ứng dụng. Hãy kiểm tra mạng rồi tải lại.');return}}
 if(!local){const check=async()=>{document.documentElement.style.visibility='hidden';try{const res=await fetch('/.netlify/functions/family?op=status',{credentials:'same-origin',cache:'no-store'});if([401,403].includes(res.status)){clearOfflineAccess();lock('Cần đăng nhập lại. Dữ liệu trên máy vẫn được giữ.');return}const status=res.ok?await res.json():null;if(status?.connected&&status.mode==='account'&&(status.household?.id!==window.BEP_SESSION?.household?.id||status.household?.role!==window.BEP_SESSION?.household?.role||status.household?.memberId!==window.BEP_SESSION?.household?.memberId)){location.reload();return}if(res.ok&&!status.connected){clearOfflineAccess();document.body.innerHTML='';location.replace('/login');return}if(res.ok){await rememberOfflineAccess(status);window.BEP_OFFLINE=false;document.documentElement.style.visibility='visible'}else if(!await readOfflineAccess())lock('Cần kết nối lại để đăng nhập.');else window.BEP_OFFLINE=true}catch{if(!await readOfflineAccess())lock('Quyền offline đã hết hạn. Kết nối mạng để đăng nhập lại.');else window.BEP_OFFLINE=true}finally{document.documentElement.style.visibility='visible';window.dispatchEvent(new Event('bep-connectivity'))}};window.addEventListener('pageshow',check);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()});setInterval(check,60000)}
})();
